question:
A large paper manufacturing company has 10 paper mills and supplies 1000 customers. These paper mills use three interchangeable machines and four different raw materials to produce five types of paper. The company wants to develop a plan to determine the quantity of each type of paper produced on each machine in each mill, and to determine which type of paper is supplied to which customers and in what quantity, in order to minimize total transportation costs. The following information is known:

$D_{j k}$ - Customer j requires k units of paper each month;
$r_{k l m}$ - The amount of raw material m required to produce one unit of paper of type k on machine l;
$R_{i m}$ - The amount of raw material m available each month at mill i;
$c_{k l}$ - The machine time required to produce one unit of paper of type k on machine l;
$c_{i l}$ - The machine time available each month at mill i for machine type l;
$P_{i k l}$ - The cost of producing one unit of paper of type k on machine type l at mill i;
$T_{i j k}$ - The cost of transporting one unit of paper of type k from mill i to customer j.

Develop a linear programming model for this problem.

candidates.code:
import pyomo.environ as pyo

DATA = {
    # Set sizes (problem states 10 mills, 1000 customers, 3 machines, 4 materials, 5 papers)
    "num_mills": 10,
    "num_customers": 1000,
    "num_machines": 3,
    "num_materials": 4,
    "num_papers": 5,

    # D[j][k]: customer j requires k units of paper type k each month
    "demand": {(j, k): 100.0
               for j in range(1000)
               for k in range(5)},

    # r[k][l][m]: raw material m needed per unit of paper k on machine l
    "raw_per_unit": {(k, l, m): 1.0
                     for k in range(5)
                     for l in range(3)
                     for m in range(4)},

    # R[i][m]: raw material m available each month at mill i
    "raw_avail": {(i, m): 100000.0
                  for i in range(10)
                  for m in range(4)},

    # c[k][l]: machine time required per unit of paper k on machine l
    "machine_time_per_unit": {(k, l): 1.0
                              for k in range(5)
                              for l in range(3)},

    # c[i][l]: machine time available each month at mill i for machine l
    "machine_time_avail": {(i, l): 100000.0
                           for i in range(10)
                           for l in range(3)},

    # P[i][k][l]: production cost per unit of paper k on machine l at mill i
    "prod_cost": {(i, k, l): 5.0
                  for i in range(10)
                  for k in range(5)
                  for l in range(3)},

    # T[i][j][k]: transport cost per unit of paper k from mill i to customer j
    "trans_cost": {(i, j, k): 1.0
                   for i in range(10)
                   for j in range(1000)
                   for k in range(5)},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # ---- Sets ----
    model.I = pyo.RangeSet(0, d["num_mills"] - 1)          # mills
    model.J = pyo.RangeSet(0, d["num_customers"] - 1)      # customers
    model.L = pyo.RangeSet(0, d["num_machines"] - 1)       # machines
    model.M = pyo.RangeSet(0, d["num_materials"] - 1)      # raw materials
    model.K = pyo.RangeSet(0, d["num_papers"] - 1)         # paper types

    # ---- Decision variables ----
    # produce[i,l,k]: units of paper type k produced on machine l at mill i
    model.produce = pyo.Var(model.I, model.L, model.K,
                            domain=pyo.NonNegativeReals)

    # ship[i,j,k]: units of paper type k shipped from mill i to customer j
    model.ship = pyo.Var(model.I, model.J, model.K,
                         domain=pyo.NonNegativeReals)

    # ---- Objective: minimize production + transportation cost ----
    def obj_rule(m):
        prod = sum(d["prod_cost"][(i, k, l)] * m.produce[i, l, k]
                   for i in m.I for l in m.L for k in m.K)
        trans = sum(d["trans_cost"][(i, j, k)] * m.ship[i, j, k]
                    for i in m.I for j in m.J for k in m.K)
        return prod + trans

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # ---- Constraint: raw material availability at each mill ----
    def raw_avail_rule(m, i, mat):
        return sum(d["raw_per_unit"][(k, l, mat)] * m.produce[i, l, k]
                   for l in m.L for k in m.K) <= d["raw_avail"][(i, mat)]

    model.raw_avail = pyo.Constraint(model.I, model.M, rule=raw_avail_rule)

    # ---- Constraint: machine time availability at each mill ----
    def machine_time_rule(m, i, l):
        return sum(d["machine_time_per_unit"][(k, l)] * m.produce[i, l, k]
                   for k in m.K) <= d["machine_time_avail"][(i, l)]

    model.machine_time = pyo.Constraint(model.I, model.L, rule=machine_time_rule)

    # ---- Constraint: each customer's demand for each paper type is met ----
    def demand_rule(m, j, k):
        return sum(m.ship[i, j, k] for i in m.I) == d["demand"][(j, k)]

    model.demand = pyo.Constraint(model.J, model.K, rule=demand_rule)

    # ---- Constraint: flow balance (shipped = produced at each mill, per paper) ----
    def balance_rule(m, i, k):
        return sum(m.ship[i, j, k] for j in m.J) == sum(m.produce[i, l, k] for l in m.L)

    model.balance = pyo.Constraint(model.I, model.K, rule=balance_rule)

    return model


